from pathlib import Path
from html import escape as e
import json,re,shutil,datetime,os
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'dist';OUT.mkdir(exist_ok=True);(OUT/'assets').mkdir(exist_ok=True)
for old in OUT.glob('*.html'):old.unlink()
CONFIG=json.loads((ROOT/'data/config.json').read_text());URL=(os.getenv('SITE_URL') or ('https://'+os.environ['VERCEL_PROJECT_PRODUCTION_URL'] if os.getenv('VERCEL_PROJECT_PRODUCTION_URL') else CONFIG['url'])).rstrip('/');S=json.loads((ROOT/'data/state.json').read_text());C=json.loads((ROOT/'data/city.json').read_text());PAGES=[]
def date(value):return datetime.date.fromisoformat(value[:10]).strftime('%b %d, %Y').replace(' 0',' ')
def norm_address(address):
 s=re.split(r',|\bsuite\b|\bste\b|#',address.lower())[0]
 for long,short in [('street','st'),('avenue','ave'),('boulevard','blvd'),('road','rd'),('drive','dr'),('circle','cir'),('north','n'),('south','s'),('west','w'),('east','e')]:s=re.sub(r'\b'+long+r'\b',short,s)
 tokens=re.findall(r'[a-z0-9]+',s)
 return ' '.join(sorted(set(tokens)))
def clean(value):return '' if value in [None,'Data Not Available','NA','N/A'] else str(value)
records=[]
for r in S['records']:
 r=dict(r);r['displayName']=clean(r.get('businessDbaName')) or clean(r.get('businessLegalName')) or r['licenseNumber'];r['url']='license-'+r['licenseNumber'].lower()+'.html';r['cityMatches']=[c for c in C['records'] if norm_address(c['address'])==norm_address(r['premiseStreetAddress'])]
 r['searchText']=' '.join([r['displayName'],r['businessLegalName'],r['licenseNumber'],r['premiseStreetAddress']]+[c['name'] for c in r['cityMatches']]);records.append(r)
records.sort(key=lambda r:(r['licenseStatus'] not in ['Active','About to Expire'],r['displayName'].lower(),r['premiseStreetAddress'],r['licenseNumber']))
def dcc(r):return 'https://search.cannabis.ca.gov/results/'+str(r['id'])
def badge(r):return '<span class="badge '+('active' if r['licenseStatus'] in ['Active','About to Expire'] else 'other')+'">State: '+e(r['licenseStatus'])+'</span>'
def recordcard(r):
 city='Address appears on the city list' if r['cityMatches'] else 'City address match needs review'
 return '<article class="record" data-record="'+e(r['licenseNumber'])+'">'+badge(r)+'<h3><a href="'+r['url']+'">'+e(r['displayName'])+'</a></h3><p class="address">'+e(r['premiseStreetAddress'])+'<br>San Jose, CA '+e(r['premiseZipCode'])+'</p><span class="number">'+e(r['licenseNumber'])+'</span><p class="city-line">'+city+'</p><div class="record-foot"><a href="'+r['url']+'">View record ↗</a><span>'+('Microbusiness' if 'Microbusiness' in r['licenseType'] else 'Retailer')+'</span></div></article>'
def sponsor(all=False):
 cards=[('Purple Lotus Cannabis Dispensary','DISPENSARY','Cannabis dispensary with Commercial Street and downtown San Jose locations.','business-purple-lotus.webp','Purple Lotus dispensary exterior','https://plpcsanjose.com/')]
 if all:
  for b in json.loads((ROOT/'data/featured-businesses.json').read_text())['businesses']:
   if not b.get('sponsored'):cards.append((b['name'],b['category'].upper(),b['description'],b['image'],b['alt'],''))
 html=''
 for name,category,desc,img,alt,link in cards:
  heading='<a href="'+link+'" rel="sponsored noopener" target="_blank">'+name+'</a>' if link else name
  html+='<article class="business-card"><img class="business-photo" src="assets/'+img+'" alt="'+alt+'" width="600" height="360" loading="lazy"><div class="business-copy"><div class="business-category"><span>'+category+'</span>'+('<span class="business-sponsored">Sponsored</span>' if link else '')+'</div><h3>'+heading+'</h3><p>'+desc+'</p></div></article>'
 return '<section class="businesses wrap"><h2>Featured San Jose businesses</h2><div class="business-grid">'+html+'</div></section>' if all else '<aside class="business-spotlight wrap" aria-label="Publication sponsor">'+html+'</aside>'
def page(file,title,desc,body,schema=None):
 PAGES.append(file);canonical=URL+'/'+('' if file=='index.html' else file)
 ld={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':canonical,'isPartOf':{'@type':'WebSite','name':'CHECK THE SHOP','url':URL}}
 if schema:ld.update(schema)
 nav='<a href="index.html#lookup">Check a shop</a><a href="guides.html">Field guide</a><a href="sources.html">Sources</a>'
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | CHECK THE SHOP</title><meta name="description" content="'+e(desc,quote=True)+'"><link rel="canonical" href="'+canonical+'"><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script><script type="application/ld+json">'+json.dumps(ld).replace('</','<\\/')+'</script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap"><a class="wordmark" href="index.html">CHECK<span>THE SHOP.</span></a><nav class="navlinks" aria-label="Main navigation">'+nav+'<span class="age">21+</span></nav></div></header><main id="main">'+body+(sponsor() if file!='index.html' else '')+'</main><footer><div class="wrap"><p>CHECK THE SHOP · San Jose<br>Public records, explained. A third-party tool, not a government service.<br>License status is shown as recorded on '+date(S['checked_at'])+'.</p><nav aria-label="Footer"><a href="about.html">About</a><a href="sources.html">Sources & updates</a><a href="privacy.html">Privacy</a></nav></div></footer><script id="site-data" type="application/json">'+json.dumps({'checked_at':S['checked_at'],'city_date':C['source_date'],'records':records}).replace('</','<\\/')+'</script></body></html>'
 (OUT/file).write_text(html)
def sub(title,desc):return '<section class="subhero"><div class="wrap"><a href="index.html">← Back to the checker</a><h1>'+e(title)+'</h1><p>'+e(desc)+'</p></div></section>'
GUIDES=[('two-checks','One shop. Two records.','How a state license and San Jose registration fit together.'),('names-and-addresses','The sign isn’t always the legal name.','How to match a familiar storefront to its public record.'),('no-match','Can’t find the shop? Start here.','What to check before drawing a conclusion from a missing result.')]
def guides():return '<div class="guide-links">'+''.join('<a class="guide-link" href="guide-'+slug+'.html">'+title+' ↗</a>' for slug,title,_ in GUIDES)+'</div>'
home='''<section class="hero"><div class="wrap"><div class="edition"><span>San Jose / California</span><span>Look it up. Know before you go.</span></div><div class="hero-grid"><h1>IS THAT SHOP<br><em>LICENSED?</em></h1><p>Check a San Jose dispensary by name, address or license number. See the state record, compare the city listing, and follow the evidence.</p></div><form id="lookup" class="search-panel"><label for="shop-search">Which shop are you checking?</label><div class="search-row"><div class="typeahead"><input id="shop-search" type="search" placeholder="Shop name, street or license number…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="suggestions" aria-expanded="false"><ul id="suggestions" class="suggestions" role="listbox" hidden></ul></div><button class="button lime" type="submit">Check the shop ↗</button></div><div class="search-foot"><span>Names change. Try the street address too.</span><a href="sources.html">State records checked '''+date(S['checked_at'])+'''</a></div></form></div></section>'''+sponsor(True)+'''<section class="section" id="results"><div class="wrap"><div class="section-title"><div><p class="eyebrow">The public record</p><h2>Find the record.<br>Check the details.</h2></div><p id="result-count" aria-live="polite">'''+str(len(records))+''' license records · San Jose</p></div><p id="freshness" class="stale" hidden></p><div class="filters" aria-label="License status"><button class="filter" data-filter="all" aria-pressed="true">All records</button><button class="filter" data-filter="active" aria-pressed="false">Active state licenses</button><button class="filter" data-filter="other" aria-pressed="false">Other state statuses</button></div><p class="search-foot">A license record is not a review or a live inspection. One address may have several records. Status shown as of '''+date(S['checked_at'])+'''.</p><div id="empty" class="empty" hidden><h3>No match in this snapshot.</h3><p>That does not establish that a business is unlicensed. Try its legal name, another spelling, or the address. This tool covers records with San Jose premises, so an out-of-city delivery business may not appear.</p><a class="button" href="https://search.cannabis.ca.gov/" target="_blank" rel="noopener">Search California’s full register ↗</a><p><a href="guide-no-match.html">What to check next</a></p></div><div class="records" id="record-list">'''+''.join(recordcard(r) for r in records)+'''</div><noscript><p>JavaScript enables filtering. You can still browse every license record above.</p></noscript></div></section><section class="section notes"><div class="wrap"><div class="note-grid"><article><span class="note-number">01</span><h3>Match the address.</h3><p>A familiar name can belong to more than one location. Check the actual premises on the license.</p></article><article><span class="note-number">02</span><h3>Read the status.</h3><p>An old license number still exists after its status changes. Open the current state record.</p></article><article><span class="note-number">03</span><h3>Check the city, too.</h3><p>The state license and the city registration are different records. We keep both visible.</p></article></div></div></section><section class="section"><div class="wrap"><h2>A few things worth knowing.</h2>'''+guides()+'</div></section>'
page('index.html','Is this San Jose dispensary licensed?','Search San Jose dispensaries by name, address or license number. Compare DCC license status with the city registration list.',home)
for r in records:
 fields=[('License number',r['licenseNumber']),('State status',r['licenseStatus']),('License type',r['licenseType']),('Designation',r['licenseDesignation']),('Legal business name',r['businessLegalName']),('DBA / trade name',clean(r['businessDbaName']) or 'Not supplied in this record'),('Premises',r['premiseStreetAddress']+', San Jose, CA '+r['premiseZipCode']),('Issue date',date(r['issueDate'])),('Expiration date',date(r['expirationDate'])),('Records checked',date(S['checked_at']))]
 matched=r['cityMatches']
 citytext='<span class="badge neutral">Address appears on city list</span><p>The city lists '+ '; '.join('<strong>'+e(c['name'])+'</strong> at '+e(c['address']) for c in matched)+'.</p><p>This is an address match. Compare the city’s business name with the state license holder, especially after a change of ownership or branding.</p>' if matched else '<span class="badge other">City match needs review</span><p>We did not match this address to the city list dated '+date(C['source_date'])+'. That is not a finding that the business is unregistered. Names, addresses and publication dates can differ.</p>'
 same=[x for x in records if x['licenseNumber']!=r['licenseNumber'] and norm_address(x['premiseStreetAddress'])==norm_address(r['premiseStreetAddress'])]
 body=sub(r['displayName'],r['premiseStreetAddress']+' · San Jose')+'<section class="section"><div class="wrap detail-grid"><article class="detail-panel">'+badge(r)+'<h2 style="margin-top:22px">California license record</h2><dl class="fields">'+''.join('<dt>'+e(k)+'</dt><dd>'+e(str(v))+'</dd>' for k,v in fields)+'</dl><p>Record status is a snapshot, not a guarantee of current operations. Check the official entry for changes before relying on it.</p><div class="source-links"><a class="button" href="'+dcc(r)+'" target="_blank" rel="noopener">Open the state record ↗</a><button class="button light" data-share>Copy record link</button></div><p id="share-status" role="status"></p></article><aside><div class="detail-panel"><p class="eyebrow">The local check</p><h2>San Jose registration</h2>'+citytext+'<p>City list dated <strong>'+date(C['source_date'])+'</strong>.</p><a href="'+C['source']+'" target="_blank" rel="noopener">Open the city list ↗</a><p><a href="sources.html">How we match records</a></p></div>'
 if same:body+='<div class="detail-panel" style="margin-top:24px"><h2>Other records at this address</h2><ul class="mini-links">'+''.join('<li><a href="'+x['url']+'">'+e(x['displayName'])+'</a><small>'+e(x['licenseNumber'])+' · '+e(x['licenseStatus'])+'</small></li>' for x in same)+'</ul><p>These records share an address. That alone does not establish common ownership.</p></div>'
 body+='</aside></div></section><section class="section"><div class="wrap">'+guides()+'</div></section>'
 page(r['url'],r['displayName']+' license '+r['licenseNumber'],r['displayName']+' state license details, premises address and San Jose city-list comparison. Status checked '+date(S['checked_at'])+'.',body,schema={'citation':[dcc(r),C['source']],'dateModified':S['checked_at'][:10]})
page('guides.html','The license-checking field guide','How to read a cannabis license record and compare it with a San Jose city listing.',sub('A license number is a starting point.','Read the name, the location and the status together.')+'<section class="section"><div class="wrap">'+guides()+'</div></section>')
copy={
 'two-checks':'''<p>A shop can appear in more than one public register because those registers answer different questions. California’s Department of Cannabis Control records state licenses. San Jose publishes a list of businesses registered with the city. Looking at one does not replace looking at the other.</p><h2>Start with the state record</h2><p>Open the license entry and read its status, premises and license type together. An active license covers the activities allowed under that license at its listed location. A license for another address is not the same record, even if the sign outside has the same brand name.</p><p>“About to Expire” still counts as active in DCC’s status explanation. Other status labels need their own reading. The official entry is the place to resolve a status that has changed since this tool’s last check.</p><h2>Then compare the city listing</h2><p>Our city check matches premises addresses to the dated SJPD list. It shows the name the city uses, so you can compare it with the state’s legal name and trade name. An address match is useful evidence to examine. It does not prove that two differently named companies have the same owners.</p><h2>Look at the dates</h2><p>The date a source published its list and the date we retrieved a record are separate. A recent check of an older list does not make that list newly issued. Both dates remain visible in the checker.</p><p>Next: <a href="guide-names-and-addresses.html">How to match names and addresses</a>, or <a href="index.html#lookup">look up a shop</a>.</p><p>Sources: <a href="https://www.cannabis.ca.gov/resources/search-for-licensed-business/">DCC license status definitions</a> and <a href="'''+C['source']+'''">SJPD’s registered-business list</a>.</p>''',
 'names-and-addresses':'''<p>The name on a storefront may be a trade name, a product brand or a name carried over from a previous operator. The state record also includes a legal business name. Those fields are worth reading separately.</p><h2>Search the street first</h2><p>If a name produces nothing, try the street number and street name. This checker searches legal names, trade names, license numbers and the city names associated with a matching address. It treats common street abbreviations and direction words consistently.</p><p>Compare suite numbers yourself. Our city matching uses the street address because one source may omit a suite that another includes. A shared building can house more than one business. The full address remains visible on the record page.</p><h2>Keep different licenses separate</h2><p>You may find two active records at the same address, or an older inactive record beside a newer active one. Each license has its own number and status. An expired record does not establish that every business now operating at that address is unlicensed.</p><p>Open each relevant state entry. Compare the trade name, legal name, premises and license type. If an operator gives you a license number, search that exact number rather than relying only on the brand.</p><h2>Ask a precise question</h2><p>“Which license number covers this location?” is more useful than “Are you legit?” Keep the number and check the official state entry. If the city and state records still do not line up, ask the regulator about that specific name and address.</p><p>Next: <a href="guide-no-match.html">What to do when there is no match</a>, or <a href="index.html#lookup">search an address</a>.</p><p>Source: <a href="https://search.cannabis.ca.gov/">California’s public license records</a>.</p>''',
 'no-match':'''<p>A blank search result is a reason to keep checking. It is not a verdict. This tool holds a dated snapshot of retail-related state records with San Jose premises, plus a separate city-list comparison. It does not contain every California cannabis business.</p><h2>Try three searches</h2><ol><li>Search the street number and street name. This can find a record published under a name you do not recognize.</li><li>Search the exact license number shown by the business. Check every digit.</li><li>Open California’s full search tool and look beyond San Jose. A delivery provider may have its licensed premises in another city.</li></ol><h2>When an address differs</h2><p>A suite omitted from one source, a misspelling, a different street number or an older listing can prevent a match. We keep unmatched records visible instead of silently resolving the discrepancy. Read the full source entries and ask for clarification if needed.</p><h2>When the status differs</h2><p>Use the official state entry for the latest published status. DCC describes its search tool as updated daily. This site displays its own retrieval date and preserves its last valid snapshot if a refresh fails.</p><h2>Ask the right office</h2><p>For the state record, use <a href="https://www.cannabis.ca.gov/about-us/contact-us/">DCC’s contact page</a>. For the San Jose listing, the Division of Cannabis Regulation publishes DCR@sanjoseca.gov and (408) 537-1420. Give the office the business name, address and license number so it can check the specific record.</p><p>Next: <a href="guide-two-checks.html">Understand the two checks</a>, or <a href="https://search.cannabis.ca.gov/">open the statewide register</a>.</p><p>Sources: <a href="https://www.cannabis.ca.gov/resources/search-for-licensed-business/">DCC search guidance</a> and <a href="'''+C['source']+'''">SJPD’s consumer guidance</a>.</p>'''}
for slug,title,desc in GUIDES:page('guide-'+slug+'.html',title,desc,sub(title,desc)+'<section class="section"><article class="wrap prose">'+copy[slug]+'</article></section><section class="section"><div class="wrap">'+guides()+'</div></section>')
city_method=('Reviewed through indexed official-page text on ' if 'index' in C.get('method','') else 'Last successful retrieval: ')+date(C['reviewed_at'])+'.'
refresh=json.loads((ROOT/'data/refresh-status.json').read_text())
city_failed=any(c['source']=='SJPD' and c['status']=='error' for c in refresh['checks'])
city_access=('The latest direct refresh could not retrieve a validated city list. The last reviewed list stays visible with its original date.' if city_failed else 'The latest direct city-list refresh succeeded.')
sources='''<h2>California records</h2><p>We retrieve San Jose premises records from the public data endpoint used by the <a href="https://search.cannabis.ca.gov/">DCC License Search Tool</a>. The snapshot includes retailer licenses and microbusiness licenses with a retail activity. We keep inactive records because an old license number may be the number someone is trying to check.</p><p>Last successful retrieval: <strong>'''+date(S['checked_at'])+'''</strong>. The current snapshot contains '''+str(len(records))+''' license records. Names, license numbers, statuses, types, dates and premises addresses come from those records. We omit personal owner names and contact details.</p><h2>San Jose records</h2><p>The local comparison uses <a href="'''+C['source']+'''">SJPD’s “Be Confident, Buy Legal” list</a>, dated <strong>'''+date(C['source_date'])+'''</strong>. It contains '''+str(len(C['records']))+''' entries. '''+city_method+' '+city_access+''' A check or access failure does not change the city list’s publication date or a business’s status.</p><h2>How matching works</h2><p>We normalize punctuation, common street abbreviations and direction words, then compare street-address tokens. Suite numbers are excluded from automatic matching because the city may omit them. Full addresses are printed for comparison. An address match does not prove shared ownership or confirm that a differently named licensee is the city’s registered operator.</p><p>We do not silently change street numbers. For example, a city entry and state entry with different street numbers remain unmatched. A “needs review” result describes the match, not the legality of the business.</p><h2>Updates</h2><p>The refresh script checks the official sources, validates the response and keeps the last successful snapshot if a source is unavailable. Each source retains its own successful retrieval date. Search-index review and a direct fetch are recorded separately. A failed fetch is never counted as a successful update.</p><p>The repository includes a daily scheduled refresh for GitHub deployments. The hosted version is refreshed by its configured schedule. <a href="data.json">Download the current public data</a>.</p><h2>Sponsorship</h2><p>Paid placements are labeled Sponsored. Sponsorship does not change search order, license status or matching. Results are ordered by recorded status, then alphabetically. Purple Lotus appears in the same source-based results as other businesses.</p><h2>Related reading</h2><p><a href="guide-two-checks.html">One shop, two records</a> · <a href="guide-no-match.html">When there is no match</a></p>'''
page('sources.html','Sources, matching and updates','Official sources, actual retrieval dates and the limits of address matching.',sub('Show the record. Show the date.','How CHECK THE SHOP reads, matches and refreshes public records.')+'<section class="section"><article class="wrap prose">'+sources+'</article></section>')
page('about.html','About CHECK THE SHOP','A San Jose tool for reading cannabis license and registration records.',sub('A quick check before you go.','CHECK THE SHOP makes public cannabis records easier to read.')+'<section class="section"><article class="wrap prose"><p>The question is simple: is this the licensed business I think it is? Answering it can mean comparing an unfamiliar legal name, a storefront address and records held by two different agencies.</p><p>This tool brings those details into one place. Search a name, street or license number, then open the source record. The aim is to help you ask a better question when the details do not agree.</p><h2>What a result means</h2><p>A result shows the state’s recorded license status and an address comparison with San Jose’s dated registration list. It is not a review, a safety certification or an official government determination.</p><h2>Corrections</h2><p>If the official record is wrong, contact the agency that maintains it. If this tool and the official source differ, rely on the current official source and check the dates on our <a href="sources.html">sources page</a>.</p><h2>Photography</h2><p>Business photographs show the places featured in the homepage cards. <a href="photo-credits.html">View image sources and credits</a>.</p><p><a href="index.html#lookup">Check a shop</a> · <a href="guides.html">Read the field guide</a></p></article></section>')
page('privacy.html','Privacy','How searches are handled by CHECK THE SHOP.',sub('Your search stays in your browser.','No account or street-address submission is needed.')+'<section class="section"><article class="wrap prose"><p>Searches and filters run locally against the published snapshot. This site does not send your search text to an advertising service or to a retailer. We do not place orders or collect identity documents.</p><p>Opening an official source or sponsored link takes you to another website with its own privacy practices. Fonts load from Google Fonts, and the hosting provider processes normal requests needed to deliver the website.</p><p>Shared record links contain the public license-record URL. No personal shopping data is included.</p><p><a href="about.html">About the tool</a> · <a href="sources.html">Sources</a></p></article></section>')
# Retained credits for the real business photographs already used by the publications.
credits=json.loads((ROOT/'data/photo-credits.json').read_text())
page('photo-credits.html','Photo credits','Sources and credits for business photography.',sub('Photo credits','The real places shown in the business cards.')+'<section class="section"><div class="wrap prose"><ul>'+''.join('<li>'+e(p.get('author',''))+' · <a href="'+e(p['source'],quote=True)+'">'+e(p['alt'])+'</a></li>' for p in credits)+'</ul><a href="about.html">About the tool</a></div></section>')
page('404.html','Page not found','Return to the San Jose dispensary license checker.',sub('Let’s check that address.','This page does not exist. The license checker is on the homepage.')+'<section class="section"><div class="wrap"><a class="button" href="index.html">Open the checker</a></div></section>')
for f in ['style.css','app.js']:shutil.copy(ROOT/'src'/f,OUT/'assets'/f)
(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="6" fill="#2545ed"/><text x="20" y="29" text-anchor="middle" font-family="Arial" font-size="29" font-weight="bold" fill="#e0ef5d">C</text></svg>')
(OUT/'data.json').write_text(json.dumps({'state_checked_at':S['checked_at'],'city_source_date':C['source_date'],'city_source':C['source'],'state_source':S['source'],'records':records},indent=2))
