(OUT/'llms.txt').write_text('# CHECK THE SHOP\n\nSan Jose cannabis license-record lookup. State status and city address matches are separate. Results are dated snapshots, not findings of legality.\n\n'+''.join('- ['+title+']('+URL+'/guide-'+slug+'.html)\n' for slug,title,_ in GUIDES)+'\n- [Sources]('+URL+'/sources.html)\n- [Public data]('+URL+'/data.json)\n')
print(json.dumps({'pages':len(PAGES),'records':len(records),'city_entries':len(C['records']),'matched_records':sum(bool(r['cityMatches']) for r in records)}))
